import{_ as r,l as n,o as e,c as o,v as t,p as s,x as l,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"训练中评测与早期信号","description":"","frontmatter":{"title":"训练中评测与早期信号","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/in-training-eval.md","filePath":"llm/in-training-eval.md","lastUpdated":1789023840000}'),h={name:"llm/in-training-eval.md"};function A(m,a,_,c,f,B){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="训练中评测与早期信号" tabindex="-1">训练中评测与早期信号 <a class="header-anchor" href="#训练中评测与早期信号" aria-label="Permalink to &quot;训练中评测与早期信号&quot;">​</a></h1><div class="epigraph"><p>等到训完再看基准，万卡小时已经花完；在训练路上用隔离的、去污染的探针看曲线，才能决定是停、是退火，还是查数据。</p><footer>—— 对照 Kaplan 等扩展律实验中的沿途评估；OLMo 等开源配方的 in-loop 评测</footer></div><p><a href="/llm/training-replay">上一课</a>要求评测本身也可复现。预训练默认只打训练损失，损失降、下游可以不升，或因污染而假升。本课不重讲种子。缺口是：在训练循环里插入评测的预算、隔离与信号解释——什么叫早期，什么时候该触发退火或停跑，而不让评测进程变成落后者。数据加载下一课会争同一条磁盘；本课先把评测从训练栅栏上拿开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩展律工作沿训练曲线评估损失；产品还要代码、数学、多语言探针。频率太高，计算税与污染风险（解码写回）都涨；太低，发现配比错误时已经过了退火点。去污染课规定评测文本不得进训练存储；训练中评测还规定：评测器读独立权重快照（可以是异步检查点的只读副本），写到独立前缀。</p><p>信号解释：网页损失与指令探针可能分叉。应用帕累托，而不是把单一 C4 loss 当停训条件。DoReMi 的最差桶损失也可以当早期信号，但那是训练损失不是下游。</p><h3 id="不要在同步路径上做全量基准" tabindex="-1">不要在同步路径上做全量基准 <a class="header-anchor" href="#不要在同步路径上做全量基准" aria-label="Permalink to &quot;不要在同步路径上做全量基准&quot;">​</a></h3><p>全员等一轮 MMLU 会制造周期性落后者。应：降频（每 \\(N\\) 步）、子集样本、专用评测作业读检查点、或只在 DP 组的一部分 rank 上评再广播标量。结果写入实验追踪，带上检查点 id 与指纹库版本，满足重放。</p><p><span class="marginnote">生成式评测的温度与解码长度必须固定。把「早期信号」做成随机采样聊天，曲线不可读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选少数便宜探针（语言建模持出、短代码补全、短指令遵循）做高频；贵的闭卷基准只在检查点上低频跑。高频探针的数据来自持出，且走同一去污染清单的反向：它们自己也不能进训练。与退火表对齐：进入 \\(T_{\\mathrm{anneal}}\\) 前后加密度，以便决定是否回滚退火。</p><p>异常检测：探针突然跳升，先走重放该检查点，再怀疑弹性或脏数据。不要自动改 \\(w\\)——那是用评测在线做课程，污染协议禁止。</p><h3 id="与词表、fertility" tabindex="-1">与词表、fertility <a class="header-anchor" href="#与词表、fertility" aria-label="Permalink to &quot;与词表、fertility&quot;">​</a></h3><p>多语言探针应按字符预算截断，否则早期信号只是在报 fertility。这一点直接继承分词公平课，评测配置里写死单位。</p><p><span class="marginnote">MoE 评测时路由应与训练一致（同一 \\(k\\)、同一噪声关断策略），否则信号跟踪的是另一模型。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>训练损失跟踪的是 \\(p_{\\mathrm{train}}\\) 上的负对数似然。探针跟踪的是你声称关心的 \\(p_{\\mathrm{eval}}\\)。两者的相关在尺度与配比上会变，所以需要沿途点，而不是终点一个点。早期的含义是：在学习率仍高、回滚仍便宜时看到 \\(p_{\\mathrm{eval}}\\) 的方向。这依赖异步检查点提供足够密的只读快照。</p>',17)),(e(),s(E,null,{default:l(()=>[d(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20CKPT%5B%22%E5%8F%AA%E8%AF%BB%E6%A3%80%E6%9F%A5%E7%82%B9%E5%89%AF%E6%9C%AC%22%5D%20--%3E%20FAST%5B%22%E9%AB%98%E9%A2%91%E4%BE%BF%E5%AE%9C%E6%8E%A2%E9%92%88%22%5D%0A%20%20CKPT%20--%3E%20SLOW%5B%22%E4%BD%8E%E9%A2%91%E8%B4%B5%E5%9F%BA%E5%87%86%22%5D%0A%20%20FAST%20--%3E%20DEC%5B%22%E4%BA%BA%E5%B7%A5%E5%86%B3%E7%AD%96%EF%BC%9A%E7%BB%AD%20%2F%20%E9%80%80%E7%81%AB%20%2F%20%E5%81%9C%22%5D%0A%20%20SLOW%20--%3E%20DEC%0A%20%20DEC%20--%3E%20NO%5B%22%E7%A6%81%E6%AD%A2%E8%87%AA%E5%8A%A8%E6%94%B9%E9%85%8D%E6%AF%94%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>早期信号不能替代完整评测包，也看不见尚未出现的涌现。它不负责数据读取吞吐——若评测与训练抢加载器，两者一起饿死。下一课把训练侧的数据流水单独做成预取、解码、GPU 投递的管道，评测作业不得接入同一预取队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲重放种子；只补隔离的沿途探针与决策纪律。</li><li>评测读独立快照、写独立存储；高频便宜、低频完整。</li><li>禁止用探针在线改 \\(w\\)；异常先重放。</li><li>截断单位按字符，避免 fertility 假信号。</li><li>出处：Kaplan et al. 扩展律沿途评估；Groeneveld et al., OLMo；去污染对照 Brown / Lee。</li></ul>',4))])}const D=r(h,[["render",A]]);export{T as __pageData,D as default};
